#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize, JsonSchema)]
#[serde(rename_all = "camelCase")]
pub struct LockfileRefreshResult {
    pub filename: PathBuf,
    pub refresh_command: String,
    pub success: bool,
    pub exit_code: Option<i32>,
}

/// Status report output from `callisto status --format json`.
#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize, JsonSchema)]
#[serde(rename_all = "camelCase")]
pub struct StatusReport {
    pub schema_version: u32,
    /// Mandatory — the field the Action's mode dispatch reads.
    /// Always serialized, never omitted, even when `false`.
    pub has_changesets: bool,
    /// Count of packages with a planned bump (`StatusPackageRecord.pending_severity.is_some()`),
    runner: &R,
    root: &Path,
    dir: &Path,
    file: &str,
    program: &str,
    args: &[&str],
) -> Result<LockfileRefreshResult, GraphError> {
    run_lockfile_refresh(
        runner,
        &root.join(dir),
        &dir.join(file).to_string_lossy(),
        program,
        args,
    )
}

/// The workspace directories, relative to the workspace root, whose npm-family and Python lockfiles the plan's writes
/// affect: each package's owning workspace, so one below the root keeps its own.
#[derive(Default)]
struct LockfileDirs {
    npm: BTreeSet<PathBuf>,
    pypi: BTreeSet<PathBuf>,
}

fn lockfile_dirs(
    root: &Path,
    plan: &VersionPlan,
    active_ecosystems: &HashSet<Ecosystem>,
) -> Result<LockfileDirs, GraphError> {
    let mut dirs = LockfileDirs::default();
    for manifest in written_manifests(plan) {
        match ManifestFormat::from_path(manifest)
            .ok()
            .map(|format| format.ecosystem())
        {
            Some(Ecosystem::Npm) => {
                dirs.npm.insert(npm_workspace_dir(root, package_dir_of(manifest))?);
            }
            Some(Ecosystem::Pypi) => {
                dirs.pypi.insert(python_workspace_dir(root, package_dir_of(manifest))?);
            }
            _ => {}
        }
    }
    // A plan that names an ecosystem but writes none of its manifests refreshes the workspace root's lockfile.
    if active_ecosystems.contains(&Ecosystem::Npm) && dirs.npm.is_empty() {
        dirs.npm.insert(PathBuf::new());
    }
    if active_ecosystems.contains(&Ecosystem::Pypi) && dirs.pypi.is_empty() {
        dirs.pypi.insert(PathBuf::new());
    }
    Ok(dirs)
}

/// The directory of a package whose manifest is `manifest`.
fn package_dir_of(manifest: &Path) -> &Path {
    manifest.parent().unwrap_or(Path::new(""))
}

/// Maps a non-zero exit to `GraphError::LockfileRefreshFailed`, an exec failure to `GraphError::Command`.
fn run_lockfile_refresh<R: CommandRunner>(
    runner: &R,
    root: &Path,
    filename: &str,
    program: &str,
    args: &[&str],
) -> Result<LockfileRefreshResult, GraphError> {
    let refresh_command = format!("{program} {}", args.join(" "));
    let out = runner.run(program, args, root)?;
    if !out.success() {
        return Err(GraphError::LockfileRefreshFailed {
            filename: PathBuf::from(filename),
            refresh_command,
            exit_code: out.exit_code,
            stderr: out.redacted_stderr(),
        });
    }
    Ok(LockfileRefreshResult {
        filename: PathBuf::from(filename),
        refresh_command,
        success: true,
        exit_code: out.exit_code,
    })
}

